<?php
namespace App\Filament\Resources\Collections;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Collections\Pages\ManageCollections; use App\Models\Collection;
use BackedEnum; use Filament\Actions\BulkActionGroup; use Filament\Actions\DeleteAction; use Filament\Actions\DeleteBulkAction; use Filament\Actions\EditAction; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\IconColumn; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table;
class CollectionResource extends AdminResource { protected static ?string $model=Collection::class; protected static string $viewPermission='catalog.view'; protected static ?string $managePermission='catalog.update'; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedRectangleStack; protected static ?string $navigationLabel='Bộ sưu tập'; protected static string|\UnitEnum|null $navigationGroup='Sản phẩm'; protected static ?int $navigationSort=60; public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->label('Tên')->required(),TextInput::make('slug')->label('Slug')->required()->unique(ignoreRecord:true),TextInput::make('banner_path')->label('Banner / URL ảnh'),DateTimePicker::make('starts_at')->label('Bắt đầu'),DateTimePicker::make('ends_at')->label('Kết thúc'),Toggle::make('is_active')->label('Hoạt động')->default(true),Textarea::make('description')->label('Mô tả')->columnSpanFull()])->columns(2);} public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Tên')->searchable(),TextColumn::make('slug')->label('Slug'),TextColumn::make('starts_at')->label('Bắt đầu')->dateTime('d/m/Y'),TextColumn::make('ends_at')->label('Kết thúc')->dateTime('d/m/Y'),IconColumn::make('is_active')->label('Bật')->boolean()])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);}public static function getPages():array{return ['index'=>ManageCollections::route('/')];}}
